    [453698] = { en = "Engrave your ring with the Nature Specialization rune:\r\n\r\n$@spellicon442896\r\n$@spelldesc442896", description = "Incidi sul tuo anello la runa di Specializzazione in natura:\r\n\r\n$@spellicon442896\r\n$@spelldesc442896" },
