    [456222] = { en = "Casting your Healing Touch or Nourish spells gives you a $h% chance to gain Mana equal to $s1% of the base cost of the spell.", description = "Lanciare i tuoi incantesimi Tocco curativo o Nutrizione ti dà una probabilità del $h% di ottenere mana pari al $s1% del costo base dell'incantesimo." },
    [456322] = { en = "Reduces the cooldown on Tranquility by $s1% and increases its healing by $s2%.", description = "Riduce il tempo di recupero di Tranquillità del $s1% e ne aumenta le cure del $s2%." },
    [456485] = { en = "Heals the target for ${$<healpower>*$m1/100*3} health over $d and applies Temporal Beacon for $400735s3 sec. \r\n\r\nTemporal Beacon\r\n$@spellicon400735\r\n$@spelldesc400735", description = "Cura il bersaglio di ${$<healpower>*$m1/100*3} salute in $d e applica Fenditura Temporale per $400735s3 sec.\r\n\r\nFenditura Temporale\r\n$@spellicon400735\r\n$@spelldesc400735" },
    [456488] = { en = "Increases the chance for allies to trigger your Judgement of Light or Judgement of Wisdom to $s1%.", description = "Aumenta al $s1% la probabilità che gli alleati attivino il tuo Giudizio della Luce o Giudizio della Saggezza." },
    [456533] = { en = "Your Seal of Command, Seal of Righteousness, Seal of Martyrdom, and Sunlight deal $s2% less damage, but now persist for $s1 seconds after you cast another Seal, or until you cast a third Seal. Your Judgements can now trigger multiple Seals if active.", description = "I tuoi Sigillo del comando, Sigillo della rettitudine, Sigillo del martirio e Raggio solare infliggono il $s2% di danni in meno, ma ora persistono per $s1 secondi dopo il lancio di un altro Sigillo, oppure finché non lanci un terzo Sigillo. I tuoi Giudizi possono ora attivare più Sigilli se sono attivi." },
    [456538] = { en = "Heal for $456540s1 when you Block. Can only heal once every few seconds.", description = "Cura di $456540s1 quando blocchi. Può curare solo una volta ogni pochi secondi." },
    [456541] = { en = "Holy Shield no longer has charges and instead always lasts its full duration. In addition, its damage is increased by $s2% of your shield block value.", description = "Scudo sacro non ha più cariche e dura sempre per tutta la sua durata. Inoltre, i suoi danni aumentano del $s2% del valore di blocco dello scudo." },
    [457021] = { en = "???", description = "???" },
    [457339] = { en = "Increases the critical strike damage bonus of your Poisons by $s1%.", description = "Aumenta del $s1% il bonus ai danni da colpo critico dei tuoi Veleni." },
    [457344] = { en = "Your finishing moves have a $b1% chance per combo point to make your next ability cost no energy.", description = "Le tue mosse finali hanno una probabilità del $b1% per punto combo di rendere gratuita in energia la tua prossima abilità." },
    [457437] = { en = "Reduces all Magic damage taken by $s1% for $d.", description = "Riduce tutti i danni magici subiti del $s1% per $d." },
    [457464] = { en = "Your finishing moves have a $b1% chance per combo point to make you take $457469s1% less Physical damage from the next melee attack that hits you within $457469d.", description = "Le tue mosse finali hanno una probabilità del $b1% per punto combo di ridurre del $457469s1% i danni fisici subiti dal prossimo attacco in mischia che ti colpisce entro $457469d." },
    [457478] = { en = "After casting your Healing Wave, Lesser Healing Wave, or Riptide spell, gives you a $h% chance to gain Mana equal to $s1% of the base cost of the spell.", description = "Dopo aver lanciato Ondata curativa, Ondata curativa inferiore o Flusso vitale, hai una probabilità del $h% di ottenere mana pari al $s1% del costo base dell'incantesimo." },
    [458287] = { en = "Your Consecration now also heals party members within its area for $s1% of Consecration's damage value.", description = "La tua Consacrazione cura anche i membri del gruppo nell'area per un ammontare pari al $s1% dei danni inflitti da Consacrazione." },
    [458318] = { en = "You can now take actions during Divine Protection and its duration is increased by $s3%, but it only reduces damage you take by $458312s1% instead of making you immune. In addition, activating Holy Shield also grants you $460171s2 Attack Power for each point of your defense skill beyond ${$PL*5}, lasting $460171d.", description = "Ora puoi compiere azioni durante Protezione divina e la sua durata aumenta del $s3%, ma riduce i danni subiti solo del $458312s1% invece di renderti immune. Inoltre, attivare Scudo sacro ti conferisce $460171s2 potere d'attacco per ogni punto della tua abilità di difesa oltre ${$PL*5}, per $460171d." },
    [458479] = { en = "Replaces your Wyvern Sting ability with Wyvern Strike, a vicious strike that deals $458436s2% weapon damage and causes the target to Bleed for damage over time.\r\n\r\nWyvern Strike requires you to have the Wyvern Sting talent, and replaces the Wyvern Sting abilities found in the Survival spellbook.", description = "Sostituisce la tua abilità Pungiglione del viverna con Colpo del viverna, un colpo feroce che infligge il $458436s2% dei danni dell'arma e fa sanguinare il bersaglio, infliggendo danni nel tempo.\r\n\r\nColpo del viverna richiede il talento Pungiglione del viverna e sostituisce le abilità Pungiglione del viverna presenti nel grimorio di Sopravvivenza." },
    [458821] = { en = "Coats a weapon with poison that lasts for 30 minutes. Each strike has a $h% chance of poisoning the enemy for $458820o1 Nature damage over $458820d and causing the enemy to take $458820s2% increased Arcane, Fire, Frost, Nature, and Shadow damage.  Stacks up to $458820u times on a single target.\r\n\r\nOccult Poison counts as Deadly Poison and benefits from all talents and effects that trigger from or modify Deadly Poison.\r\n", description = "Ricopre un'arma di veleno che dura 30 minuti. Ogni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo $458820o1 danni naturali in $458820d e aumentando del $458820s2% i danni arcani, da fuoco, da gelo, naturali e da ombra subiti dal nemico. Si accumula fino a $458820u volte sullo stesso bersaglio.\r\n\r\nVeleno occulto è considerato Veleno mortale e beneficia di tutti i talenti e gli effetti che si attivano con o modificano Veleno mortale.\r\n" },
    [458822] = { en = "Coats a weapon with poison that lasts for 30 minutes.\r\nEach strike has a 30% chance of poisoning the enemy for $458820o1 Nature damage over $458820d and causing the enemy to take $458820s2% increased Arcane, Fire, Frost, Nature, and Shadow damage.  Stacks up to $458820u times on a single target.\r\n\r\nOccult Poison counts as Deadly Poison and benefits from all talents and effects that trigger from or modify Deadly Poison.", description = "Ricopre un'arma di veleno che dura 30 minuti.\r\nOgni colpo ha una probabilità del 30% di avvelenare il nemico, infliggendo $458820o1 danni naturali in $458820d e aumentando del $458820s2% i danni arcani, da fuoco, da gelo, naturali e da ombra subiti dal nemico. Si accumula fino a $458820u volte sullo stesso bersaglio.\r\n\r\nVeleno occulto è considerato Veleno mortale e beneficia di tutti i talenti e gli effetti che si attivano con o modificano Veleno mortale." },
    [458856] = { en = "Heals a friendly target for ${$<healpower>*$m1/100} to ${$<healpower>*$M1/100}. $s2% of any excess healing on the target is converted into an absorption shield that lasts $458857d. Multiple casts of Divine Light do not accumulate this shield.\r\n\r\nDivine Light benefits from all talents and effects that trigger from or modify Holy Light.", description = "Cura un bersaglio amico da ${$<healpower>*$m1/100} a ${$<healpower>*$M1/100}. Il $s2% di ogni cura in eccesso sul bersaglio viene convertito in uno scudo di assorbimento che dura $458857d. Lanci multipli di Luce divina non accumulano questo scudo.\r\n\r\nLuce divina beneficia di tutti i talenti e gli effetti che si attivano con o modificano Luce sacra." },
