    [461253] = { en = "Activating Blade Flurry now engulfs you in Shadowflame, causing your attacks to ignore $461252s1 of your target's armor.", description = "L'attivazione di Raffica di lame ora ti avvolge in Fiamme dell'Ombra, facendo sì che i tuoi attacchi ignorino $461252s1 dell'armatura del bersaglio." },
