    [461299] = { en = "While a Shield is equipped, your melee attacks with Rockbiter Weapon restore $461300s1% of your total mana.", description = "Quando è equipaggiato uno scudo, i tuoi attacchi in mischia con Arma Rocciadura ripristinano il $461300s1% del tuo mana totale." },
