    [461314] = { en = "Make a promise to protect a party or raid member, transferring $m1% of the threat they cause to you. This effect can only be on one target at a time.", description = "Fai una promessa di proteggere un membro del gruppo o dell'incursione, trasferendo a te il $m1% della minaccia che genera. Questo effetto può essere attivo su un solo bersaglio alla volta." },
