    [461339] = { en = "..", description = ".." },
    [461402] = { en = "The imp swings the shredder's blades in a circular motion, dealing damage and knocking back enemies around him.", description = "L'imp brandisce le lame del trinciatore con un movimento circolare, infliggendo danni e respingendo i nemici attorno a sé." },
    [461463] = { en = "$@spelldesc445575", description = "$@spelldesc445575" },
    [461475] = { en = "Inspires all members of your party or raid to fight for the Valor of Azeroth, increasing critical chance of all spells and attacks by $s1% and granting ${$PL*1.5} Attack Power. Lasts $d.\r\n\r\nMay not be combined with similar long-duration effects.", description = "Ispira tutti i membri del tuo gruppo o della tua incursione a combattere per il Valore di Azeroth, aumentando del $s1% la probabilità di critico di tutti gli incantesimi e gli attacchi e conferendo ${$PL*1.5} potenza d'attacco. Dura $d.\r\n\r\nNon può essere combinato con effetti simili di lunga durata." },
    [461633] = { en = "Imbue the Shaman's weapon with frost.  Each hit has a chance of causing $16353s2 additional Frost damage and slowing the target's movement speed by $16353s1% for $16353d.  Lasts for 1 hour.", description = "Infondi l'arma dello Sciamano con il gelo. Ogni colpo ha una probabilità di infliggere $16353s2 danni da Gelo aggiuntivi e di ridurre la velocità di movimento del bersaglio del $16353s1% per $16353d. Dura 1 ora." },
    [461634] = { en = "Imbue the Shaman's weapon with fire.  Each hit causes $/77;16344m1 to $/25;16344M1 additional Fire damage, based on the speed of the weapon.  Slower weapons cause more fire damage per swing.  Lasts for 1 hour.", description = "Infondi l'arma dello Sciamano con il fuoco. Ogni colpo infligge da $/77;16344m1 a $/25;16344M1 danni da Fuoco aggiuntivi, in base alla velocità dell'arma. Le armi più lente infliggono più danni da fuoco a ogni colpo. Dura 1 ora." },
    [461635] = { en = "Imbue the Shaman's weapon, increasing melee attack power by $16313s1 and allowing melee attacks to cause additional threat when using that weapon.  Lasts for 1 hour.", description = "Infondi l'arma dello Sciamano, aumentando la potenza d'attacco in mischia di $16313s1 e permettendo agli attacchi in mischia con quell'arma di generare minaccia aggiuntiva. Dura 1 ora." },
    [461636] = { en = "Imbue the Shaman's weapon with wind.  Each hit has a 20% chance of granting you $16361s2 extra $lattack:attacks; with $16361s1 extra melee attack power.  Lasts for 1 hour.", description = "Infondi l'arma dello Sciamano con il vento. Ogni colpo ha il 20% di probabilità di conferirti $16361s2 $lattacco:attacchi; aggiuntivi con $16361s1 potenza d'attacco in mischia aggiuntiva. Dura 1 ora." },
    [461697] = { en = "Increases damage done by magical spells and effects by up to $s1.", description = "Aumenta i danni inflitti da incantesimi ed effetti magici fino a $s1." },
    [461830] = { en = "Blasts nearby enemies increasing the time between their attacks by $s2% for $d and doing $s1 damage to them.  Will affect up to $i targets.", description = "Colpisce i nemici vicini, aumentando del $s2% il tempo tra i loro attacchi per $d e infliggendo loro $s1 danni. Può colpire fino a $i bersagli." },
    [461966] = { en = "Afflicts your target with Shadow energy that causes all party members to be healed for $s1% of any Shadow spell damage you deal for $d.", description = "Affligge il bersaglio con energia dell'Ombra, facendo sì che tutti i membri del gruppo vengano curati per il $s1% dei danni inflitti dai tuoi incantesimi d'Ombra per $d." },
    [462636] = { en = "Increases your spell damage by up to $s1 and your healing by up to $s2 for $d.", description = "Aumenta i danni dei tuoi incantesimi fino a $s1 e le tue cure fino a $s2 per $d." },
    [462708] = { en = "Your Backstab has a $m1% chance to cause your next Ambush within $462707d to not require Stealth.", description = "Il tuo Agguato alle spalle ha una probabilità del $m1% di fare in modo che il tuo prossimo Agguato entro $462707d non richieda Furtività." },
    [462709] = { en = "Backstab the target, causing $s2% weapon damage plus 15 to the target.  Must be behind the target.  Requires a dagger in the main hand.  Awards $s3 combo $lpoint:points;.", description = "Colpisce il bersaglio alle spalle, infliggendo danni pari al $s2% dei danni dell'arma più 15. Devi trovarti alle spalle del bersaglio. Richiede un pugnale nella mano principale. Conferisce $s3 $lpunto:punti combo;." },
    [462710] = { en = "Backstab the target, causing $s2% weapon damage plus 30 to the target.  Must be behind the target.  Requires a dagger in the main hand.  Awards $s3 combo $lpoint:points;.", description = "Colpisce il bersaglio alle spalle, infliggendo danni pari al $s2% dei danni dell'arma più 30. Devi trovarti alle spalle del bersaglio. Richiede un pugnale nella mano principale. Conferisce $s3 $lpunto:punti combo;." },
