    [462714] = { en = "Backstab the target, causing $s2% weapon damage plus 135 to the target.  Must be behind the target.  Requires a dagger in the main hand.  Awards $s3 combo $lpoint:points;.", description = "Colpisce il bersaglio alle spalle, infliggendo danni pari al $s2% dei danni dell'arma più 135. Devi trovarti alle spalle del bersaglio. Richiede un pugnale nella mano principale. Conferisce $s3 $lpunto:punti combo;." },
    [462715] = { en = "Backstab the target, causing $s2% weapon damage plus 165 to the target.  Must be behind the target.  Requires a dagger in the main hand.  Awards $s3 combo $lpoint:points;.", description = "Colpisce il bersaglio alle spalle, infliggendo danni pari al $s2% dei danni dell'arma più 165. Devi trovarti alle spalle del bersaglio. Richiede un pugnale nella mano principale. Conferisce $s3 $lpunto:punti combo;." },
    [462716] = { en = "Backstab the target, causing $s2% weapon damage plus 210 to the target.  Must be behind the target.  Requires a dagger in the main hand.  Awards $s3 combo $lpoint:points;.", description = "Colpisce il bersaglio alle spalle, infliggendo danni pari al $s2% dei danni dell'arma più 210. Devi trovarti alle spalle del bersaglio. Richiede un pugnale nella mano principale. Conferisce $s3 $lpunto:punti combo;." },
    [462717] = { en = "Backstab the target, causing $s2% weapon damage plus 225 to the target.  Must be behind the target.  Requires a dagger in the main hand.  Awards $s3 combo $lpoint:points;.", description = "Colpisce il bersaglio alle spalle, infliggendo danni pari al $s2% dei danni dell'arma più 225. Devi trovarti alle spalle del bersaglio. Richiede un pugnale nella mano principale. Conferisce $s3 $lpunto:punti combo;." },
    [462724] = { en = "Garrote the enemy, causing $o1 damage over $d, increased by your Attack Power.  Must be stealthed and behind the target.  Awards $s2 combo $lpoint:points;.", description = "Garrotta il nemico, infliggendo $o1 danni nel tempo per $d, aumentati dalla potenza d'attacco. Richiede furtività e di trovarsi alle spalle del bersaglio. Conferisce $s2 $lpunto:punti combo;." },
    [462726] = { en = "Garrote the enemy, causing $o1 damage over $d, increased by your Attack Power.  Must be stealthed and behind the target.  Awards $s2 combo $lpoint:points;.", description = "Garrotta il nemico, infliggendo $o1 danni nel tempo per $d, aumentati dalla potenza d'attacco. Richiede furtività e di trovarsi alle spalle del bersaglio. Conferisce $s2 $lpunto:punti combo;." },
    [462727] = { en = "Garrote the enemy, causing $o1 damage over $d, increased by your Attack Power.  Must be stealthed and behind the target.  Awards $s2 combo $lpoint:points;.", description = "Garrotta il nemico, infliggendo $o1 danni nel tempo per $d, aumentati dalla potenza d'attacco. Richiede furtività e di trovarsi alle spalle del bersaglio. Conferisce $s2 $lpunto:punti combo;." },
    [462728] = { en = "Garrote the enemy, causing $o1 damage over $d, increased by your Attack Power.  Must be stealthed and behind the target.  Awards $s2 combo $lpoint:points;.", description = "Garrotta il nemico, infliggendo $o1 danni nel tempo per $d, aumentati dalla potenza d'attacco. Richiede furtività e di trovarsi alle spalle del bersaglio. Conferisce $s2 $lpunto:punti combo;." },
    [462729] = { en = "Garrote the enemy, causing $o1 damage over $d, increased by your Attack Power.  Must be stealthed and behind the target.  Awards $s2 combo $lpoint:points;.", description = "Garrotta il nemico, infliggendo $o1 danni nel tempo per $d, aumentati dalla potenza d'attacco. Richiede furtività e di trovarsi alle spalle del bersaglio. Conferisce $s2 $lpunto:punti combo;." },
    [462730] = { en = "Garrote the enemy, causing $o1 damage over $d, increased by your Attack Power.  Must be stealthed and behind the target.  Awards $s2 combo $lpoint:points;.", description = "Garrotta il nemico, infliggendo $o1 danni nel tempo per $d, aumentati dalla potenza d'attacco. Richiede furtività e di trovarsi alle spalle del bersaglio. Conferisce $s2 $lpunto:punti combo;." },
    [462834] = { en = "While Righteous Fury is not active, dealing Holy Shock damage grants $s1% of your Intellect as Spell Damage and reduces the threat you generate by $462832s2% for $462832d.\r\n\r\nIf Infusion of Light is engraved, gain Sunlight for $1239543d.\r\n\r\n$@spellicon1239543\r\nSunlight causes Divine Storm, Crusader Strike, and melee attacks against non-player controlled targets to deal bonus Holy damage equal to $s2% of your holy spell power.", description = "Quando Furia virtuosa non è attiva, infliggere danni con Esplosione sacra conferisce danni degli incantesimi pari al $s1% del tuo Intelletto e riduce la minaccia che generi del $462832s2% per $462832d.\r\n\r\nSe Infusione di Luce è incisa, ottieni Luce solare per $1239543d.\r\n\r\n$@spellicon1239543\r\nLuce solare fa sì che Tempesta divina, Assalto del crociato e gli attacchi in mischia contro bersagli non controllati da giocatori infliggano danni sacri bonus pari al $s2% della tua potenza degli incantesimi sacri." },
    [462853] = { en = "Causes target party or raid member to transfer $s1% of damage taken to the caster.  Lasts $d or until the caster has transferred $s2% of their maximum health.", description = "Fa sì che un membro del gruppo o dell'incursione trasferisca all'incantatore il $s1% dei danni subiti. Dura $d o finché l'incantatore non ha trasferito il $s2% della sua salute massima." },
    [463105] = { en = "When active, grants the wielder $s1 defense and $s2 armor for $d.", description = "Quando è attivo, conferisce a chi lo impugna $s1 difesa e $s2 armatura per $d." },
    [463146] = { en = "Your Crusader Strike spell reduces the cost of your next Consecration spell by $s1%.", description = "Il tuo Incantesimo d'Attacco del Crociato riduce del $s1% il costo del tuo prossimo incantesimo Consacrazione." },
    [463873] = { en = "Increases damage done by magical spells and effects by up to $s1, and increases healing done by magical spells and effects by up to $2.", description = "Aumenta fino a $s1 i danni inflitti dagli incantesimi ed effetti magici e aumenta fino a $2 le cure fornite dagli incantesimi ed effetti magici." },
    [464241] = { en = "Reduces the rage cost of your next offensive ability by $/10;s1.", description = "Riduce di $/10;s1 il costo in rabbia della tua prossima abilità offensiva." },
    [465700] = { en = "Directs a bolt of lightning at the enemy, dealing $s1  Nature damage and then jumping to additional nearby enemies. Each jump increases the damage. ", description = "Scaglia un fulmine contro il nemico, infliggendo $s1 danni da Natura e poi rimbalzando su altri nemici vicini. Ogni rimbalzo aumenta i danni. " },
    [466195] = { en = "Burn for $s1 Fire damage every $t1 seconds. This effect stacks.\r\n", description = "Bruci per $s1 danni da Fuoco ogni $t1 secondi. Questo effetto si accumula.\r\n" },
    [466261] = { en = "Challenging the Trial of the Red Dragonflight. When injured, burn for $s1 fire damage every $t1 seconds until healed above 90% of your maximum health. Direct heals remove 1 stack.", description = "Sfidando la Prova della Stirpe dei Draghi Rossi. Quando sei ferito, bruci per $s1 danni da fuoco ogni $t1 secondi finché non vieni curato oltre il 90% della tua salute massima. Le cure dirette rimuovono 1 accumulo." },
    [466357] = { en = "Detonates after $d, dealing heavy damage split among everyone affected.", description = "Detona dopo $d, infliggendo ingenti danni suddivisi tra tutti i bersagli colpiti." },
    [466774] = { en = "Affects nearby enemies with residual energy from the storm. Lasts for $d and inflicts nature damage per second", description = "Colpisce i nemici vicini con l'energia residua della tempesta. Dura $d e infligge danni da natura al secondo" },
    [466909] = { en = "$@spelldesc466903", description = "$@spelldesc466903" },
    [467145] = { en = "$s1% chance on ranged hit to gain 1 extra attack.", description = "Probabilità del $s1% con un colpo a distanza di ottenere 1 attacco aggiuntivo." },
    [467203] = { en = "Your non-periodic spell critical strikes reduce the casting time of your next Healing Touch, Regrowth, or Nourish spell by ${$467204m1/-1000}.1 sec.", description = "I tuoi colpi critici degli incantesimi non periodici riducono di ${$467204m1/-1000}.1 sec il tempo di lancio del tuo prossimo Tocco Curativo, Ricrescita o Nutrizione." },
    [467205] = { en = "Increases healing from Wild Growth by $s1%. In addition, Wild Growth can now be used in Moonkin Form, and its healing is increased by an additional $467206s2% in that form.", description = "Aumenta del $s1% le cure di Crescita Rigogliosa. Inoltre, Crescita Rigogliosa può ora essere usata in Forma Lunare e le sue cure in quella forma aumentano di un ulteriore $467206s2%." },
    [467207] = { en = "Increases the duration of Rake by ${$m2/1000} sec and its periodic damage by $m1%.", description = "Aumenta la durata di Dilaniamento di ${$m2/1000} sec e i suoi danni periodici del $m1%." },
    [467208] = { en = "Your critical strike chance is increased by $467209s1% while Tiger's Fury is active.", description = "La probabilità di critico aumenta del $467209s1% mentre Furia della Tigre è attiva." },
    [467211] = { en = "Your Shred, Ferocious Bite, and Mangle(Cat) abilities deal $s1% increased damage per your Bleed effect on the target, up to a maximum of $s2% increase.", description = "Le tue abilità Devastazione, Morso Feroce e Sventramento (Felino) infliggono il $s1% di danni aggiuntivi per ogni tuo effetto Sanguinamento sul bersaglio, fino a un massimo del $s2% di danni aggiuntivi." },
    [467216] = { en = "Swipe(Bear) also causes your Maul to hit $467217s1 additional target for the next $467217d.", description = "Colpo Rotante (Orso) fa sì che anche il tuo Percosse colpisca $467217s1 bersagli aggiuntivi per i prossimi $467217d." },
    [467221] = { en = "Your Mangle(Bear), Swipe(Bear), Maul, and Lacerate abilities gain $s1% increased critical strike chance against targets afflicted by your Lacerate.", description = "Le tue abilità Dilaniamento (Orso), Colpo Rotante (Orso), Percosse e Lacerare ottengono il $s1% di probabilità di critico aggiuntiva contro i bersagli affetti dal tuo Lacerare." },
    [467235] = { en = "Your Aimed Shot deals $s1% more damage to targets afflicted by one of your trap effects.", description = "Il tuo Tiro Mirato infligge il $s1% di danni aggiuntivi ai bersagli affetti da uno dei tuoi effetti trappola." },
    [467312] = { en = "Your damaging Shot abilities deal $s1% increased damage if the previous damaging Shot used was different than the current one.", description = "Le tue abilità di tiro che infliggono danni infliggono il $s1% di danni aggiuntivi se l'abilità di tiro che infliggeva danni usata in precedenza era diversa da quella attuale." },
    [467326] = { en = "Your Serpent Sting damage is increased by $s1% of your Attack Power over its normal duration.", description = "I danni di Morso del Serpente aumentano di un ammontare pari al $s1% della tua potenza d'attacco per la sua normale durata." },
    [467329] = { en = "Raptor Strike increases the damage done by your next other melee ability (excluding Wing Clip) within $467331d by $467331s1%.", description = "Colpo Rapace aumenta del $467331s1% i danni inflitti dalla tua prossima abilità da mischia diversa da Intrappolamento entro $467331d." },
    [467333] = { en = "Increases damage dealt by your main hand weapon with Raptor Strike and Wyvern Strike by $s1%.", description = "Aumenta del $s1% i danni inflitti dalla tua arma nella mano principale con Colpo Rapace e Colpo della Viverna." },
    [467334] = { en = "Your periodic damage has a $h% chance to reset the cooldown on one of your Strike abilities. The Strike with the longest remaining cooldown is always chosen.", description = "I tuoi danni periodici hanno una probabilità del $h% di azzerare il tempo di recupero di una delle tue abilità Colpo. Viene sempre scelta l'abilità Colpo con il tempo di recupero residuo più lungo." },
    [467407] = { en = "Your offensive spellcasts increase the spell damage of a random school of magic by $467414s1 for $467414d1.", description = "I tuoi lanci di incantesimi offensivi aumentano di $467414s1 i danni degli incantesimi di una scuola di magia casuale per $467414d1." },
    [467459] = { en = "Empowers your pet, increasing pet damage by $s1% and increasing pet armor by $s2% for $d. This spell does not affect temporary pets or Subjugated Demons.", description = "Potenzia il tuo famiglio, aumentandone i danni del $s1% e l'armatura del $s2% per $d. Questo incantesimo non ha effetto sui famigli temporanei o sui Demoni Soggiogati." },
    [467467] = { en = "Decreases the mana cost of all Druid shapeshifting forms by $s1%, and increases the aura effect of Moonkin Aura, Tree of Life, and Leader of the Pack by $s2% for $d.", description = "Riduce del $s1% il costo in mana di tutte le forme mutaforma del Druido e aumenta del $s2% l'effetto dell'aura di Aura Lunare, Albero della Vita e Capobranco per $d." },
    [467480] = { en = "Dismiss your pet.  Dismissing your pet will reduce its happiness by $/1000;s1.", description = "Congeda il tuo famiglio.  Congedare il famiglio ne riduce la felicità di $/1000;s1." },
    [467499] = { en = "Heals yourself for $467502s1% of your maximum health, and increases your maximum health by $467498s1% for 20 sec.", description = "Ti cura del $467502s1% della tua salute massima e aumenta la tua salute massima del $467498s1% per 20 sec." },
    [467523] = { en = "Aligns the Shaman with nature, increasing the damage done by spells by $s1%, improving heal effects by $s2%, and increasing mana cost of spells by $s3% for $d.", description = "Armonizza lo Sciamano con la natura, aumentando del $s1% i danni inflitti dagli incantesimi, migliorando del $s2% gli effetti curativi e aumentando del $s3% il costo in mana degli incantesimi per $d." },
    [467544] = { en = "Your periodic healing has a $h% chance to make your next spell with a casting time less than 10 seconds an instant cast spell.", description = "Le tue cure periodiche hanno una probabilità del $h% di rendere istantaneo il tuo prossimo incantesimo con tempo di lancio inferiore a 10 secondi." },
    [467586] = { en = "Circle of Healing and Penance also place a heal over time effect on their targets that heals for $s1% as much over $467588d.", description = "Cerchio di Guarigione e Penance applicano anche ai bersagli un effetto di cura periodica che cura per il $s1% di cure aggiuntive nell'arco di $467588d." },
    [467604] = { en = "Reduces the cooldown of your Shadow Word: Death spell by ${$m1/-1000} sec.", description = "Riduce il tempo di recupero del tuo incantesimo Parola d'Ombra: Morte di ${$m1/-1000} sec." },
    [467608] = { en = "Your Shadow Word: Pain has a ${$m1/10}.1% chance per talent point in Spirit Tap to trigger your Spirit Tap talent when it deals damage, or a $s2% chance per talent point when a target dies with your Shadow Word: Pain active. Inner Focus also has a $s2% chance per talent point to trigger Spirit Tap.", description = "La tua Parola d'Ombra: Dolore ha una probabilità del ${$m1/10}.1% per punto talento in Assorbimento di Spirito di attivare il talento Assorbimento di Spirito quando infligge danni, oppure una probabilità del $s2% per punto talento quando un bersaglio muore mentre Parola d'Ombra: Dolore è attiva. Anche Concentrazione Interiore ha una probabilità del $s2% per punto talento di attivare Assorbimento di Spirito." },
    [467624] = { en = "While Spirit Tap is active, you deal $467632s1% more Shadow damage.", description = "Mentre Assorbimento di Spirito è attivo, infliggi il $467632s1% di danni d'Ombra aggiuntivi." },
    [467708] = { en = "Your opening moves have a $h% chance to make your next ability cost no energy.", description = "Le tue mosse iniziali hanno una probabilità del $h% di rendere gratuita in energia la tua prossima abilità." },
    [467737] = { en = "Increases damage dealt by your main hand weapon from combo-generating abilities by $s1%.", description = "Aumenta del $s1% i danni inflitti dalla tua arma nella mano principale con le abilità che generano punti combo." },
    [467739] = { en = "Reduces the cooldown on Vanish to ${$m3/60000} min. Cannot be combined with Elusiveness.", description = "Riduce il tempo di recupero di Furtività a ${$m3/60000} min. Non cumulabile con Elusività." },
    [467746] = { en = "Your Rolling with the Punches now also activates every time you gain a combo point.", description = "Ora il tuo Incassare i Colpi si attiva anche ogni volta che ottieni un punto combo." },
    [467797] = { en = "Your Rolling with the Punches also grants you $s1% increased Armor from items per stack (capped at ${$s1*5}%).", description = "Il tuo Incassare i Colpi ti conferisce anche il $s1% di armatura aggiuntiva dagli oggetti per accumulo (fino a un massimo di ${$s1*5}%)." },
    [467803] = { en = "The cooldown on your Main Gauche resets every time your target Dodges or Parries.", description = "Il tempo di recupero di Parata con la Mano Sinistra si azzera ogni volta che il bersaglio schiva o para." },
    [467804] = { en = "Your non-periodic damaging and healing critical strikes now have a $h% chance to trigger your Water Shield, but do not consume a charge or trigger its cooldown.", description = "I tuoi colpi critici non periodici che infliggono danni o cure hanno ora una probabilità del $h% di attivare il tuo Scudo d'Acqua, ma non consumano una carica né attivano il suo tempo di recupero." },
    [467809] = { en = "Your Chain Lightning now also heals the target of your most recent Earth Shield for $s1% of the damage done.", description = "La tua Catena di Fulmini cura ora anche il bersaglio del tuo più recente Scudo di Terra per un ammontare pari al $s1% dei danni inflitti." },
    [467814] = { en = "Increases the healing of Chain Heal and the damage of Chain Lightning by $s1%.", description = "Aumenta del $s1% le cure di Catena di Guarigione e i danni di Catena di Fulmini." },
    [467818] = { en = "Your spell critical strikes now have a $h% chance trigger your Elemental Focus talent.", description = "I tuoi colpi critici degli incantesimi hanno ora una probabilità del $h% di attivare il talento Concentrazione Elementale." },
    [467823] = { en = "Loyal Beta from your Spirit of the Alpha ability now also increases Fire, Frost, and Nature damage by $s1%.", description = "Il Beta Leale della tua abilità Spirito dell'Alfa aumenta ora anche i danni da Fuoco, Gelo e Natura del $s1%." },
    [467836] = { en = "Zap nearby enemies dealing $s1 damage to them.  Will affect up to $i targets.", description = "Fulmina i nemici vicini, infliggendo loro $s1 danni. Colpisce fino a $i bersagli." },
    [467863] = { en = "While Clearcasting is active, you deal $s2% more non-Physical damage.", description = "Mentre Lancio Libero è attivo, infliggi il $s2% di danni non fisici aggiuntivi." },
    [467877] = { en = "Your chance to trigger Static Shock is increased by $m1% (${$m1/2}% while dual-wielding).", description = "La probabilità di attivare Shock Statico aumenta del $m1% (${$m1/2}% quando impugni due armi)." },
    [467879] = { en = "Increases the main hand damage done by your Stormstrike by $s1%.", description = "Aumenta del $s1% i danni inflitti da Assalto della Tempesta con la mano principale." },
    [467882] = { en = "While Static Shock is engraved, your Lightning Shield now gains a charge each time you hit a target with Lightning Bolt or Chain Lightning, up to a maximum of ${$432134m1+3} charges. In addition, while Static Shock is engraved, your Lightning Shield can now deal critical damage.", description = "Mentre Shock Statico è inciso, il tuo Scudo di Fulmini ottiene una carica ogni volta che colpisci un bersaglio con Dardo Fulminante o Catena di Fulmini, fino a un massimo di ${$432134m1+3} cariche. Inoltre, mentre Shock Statico è inciso, il tuo Scudo di Fulmini può ora infliggere danni critici." },
    [467889] = { en = "Your Flame Shock also grants $467891s1% increased chance to Block for $467891d or until you Block an attack.", description = "Il tuo Shock di Fiamme aumenta anche del $467891s1% la probabilità di parata per $467891d o finché non pari un attacco." },
    [467909] = { en = "Each time you Block, your Block amount is increased by $s1% of your Spell Damage for $467910d, stacking up to $467910u times.", description = "Ogni volta che blocchi, il tuo ammontare di Blocco aumenta di $s1% del tuo Danno magico per $467910d, fino a un massimo di $467910u accumuli." },
    [467916] = { en = "Each time you Block an attack, you have a $h% chance to trigger your Maelstrom Weapon rune.", description = "Ogni volta che blocchi un attacco, hai una probabilità del $h% di attivare la tua runa Arma del Maelstrom." },
    [467917] = { en = "Increases the damage of your periodic spells and Felguard pet by $s1%.", description = "Aumenta del $s1% i danni dei tuoi incantesimi periodici e del tuo famiglio Vilguardia." },
    [467983] = { en = "Periodic damage from your Shadowflame, Unstable Affliction, and Curse of Agony spells and damage done by your Felguard have a $h% chance to grant the Shadow Trance effect.", description = "I danni periodici dei tuoi incantesimi Fiamma d'Ombra, Afflizione Instabile e Maledizione dell'Agonia, e i danni inflitti dal tuo Vilguardia, hanno una probabilità del $h% di conferire l'effetto Trance dell'Ombra." },
    [467988] = { en = "Shadowbolt deals $s1% increased damage for each of your effects afflicting the target, up to a maximum of $s2%.", description = "Dardo d'Ombra infligge il $s1% di danni in più per ogni tuo effetto che affligge il bersaglio, fino a un massimo del $s2%." },
    [468028] = { en = "While you are targeting an enemy within $468029r yards, Life Tap grants you mana at the expense of your target's health but deals $s1% reduced damage to them. Mana gained remains unchanged.", description = "Quando hai come bersaglio un nemico entro $468029r metri, Trasfusione vitale ti conferisce mana a spese della salute del bersaglio, ma gli infligge il $s1% di danni in meno. Il mana ottenuto rimane invariato." },
    [468046] = { en = "While Metamorphosis is active, your offensive abilities and Demon summons cost no Soul Shards. In addition, you heal for $468062s1% of your maximum health when you damage a target with Shadowburn.", description = "Quando Metamorfosi è attiva, le tue abilità offensive e le evocazioni demoniache non costano Frammenti d'Anima. Inoltre, recuperi salute pari al $468062s1% della tua salute massima quando infliggi danni a un bersaglio con Incenerimento dell'Ombra." },
    [468061] = { en = "Any excess healing you deal to yourself  is converted into a shield that absorbs damage. This shield can absorb up to $s1% of your maximum health, and stacks from multiple heals.", description = "Ogni cura in eccesso che ti infliggi viene convertita in uno scudo che assorbe i danni. Questo scudo può assorbire fino al $s1% della tua salute massima e gli scudi di cure multiple si accumulano." },
    [468065] = { en = "You gain ${$468066m1/10} Rage every time you Parry or one of your attacks is Parried.", description = "Ottieni ${$468066m1/10} Furia ogni volta che pari o uno dei tuoi attacchi viene parato." },
    [468067] = { en = "Revenge also grants you Flurry, increasing your attack speed by $12970s1% for the next $12970n swings.", description = "Vendetta ti conferisce anche Turbine, aumentando la tua velocità d'attacco del $12970s1% per i successivi $12970n colpi." },
    [468069] = { en = "When your target Parries an attack, you instantly Retaliate for $468071s2% weapon damage to that target. Retaliate cannot be Dodged, Blocked, or Parried, but can only occur once every $468071d per target.", description = "Quando il tuo bersaglio para un attacco, contrattacchi istantaneamente infliggendo a quel bersaglio danni pari al $468071s2% dei danni dell'arma. Contrattacco non può essere schivato, bloccato o parato, ma può attivarsi solo una volta ogni $468071d per bersaglio." },
    [468072] = { en = "Overpower critical strikes refresh the duration of Rend on your target back to its maximum duration.", description = "I colpi critici di Sopraffazione ripristinano la durata di Lacerare sul bersaglio alla sua durata massima." },
    [468164] = { en = "Increases your chance to hit with all spells and attacks by $s1% for $d.", description = "Aumenta del $s1% la tua probabilità di colpire con tutti gli incantesimi e gli attacchi per $d." },
    [468195] = { en = "$@spelldesc445575", description = "$@spelldesc445575" },
    [468235] = { en = "Your Heroic Strike, Slam, and Overpower abilities deal $s1% more damage.", description = "Le tue abilità Colpo Eroico, Schianto e Sopraffazione infliggono il $s1% di danni in più." },
    [468236] = { en = "Your Slam hits reset the remaining cooldown on your Mortal Strike, Bloodthirst, and Shield Slam abilities.", description = "I colpi di Schianto azzerano il tempo di recupero rimanente delle tue abilità Colpo Mortale, Sete di Sangue e Colpo con Scudo." },
    [468252] = { en = "Clean off the rune.", description = "Pulisci la runa." },
    [468256] = { en = "$s1% chance on melee hit to gain 1 extra attack.", description = "Probabilità del $s1% a ogni colpo in mischia di ottenere un attacco extra." },
