    [468359] = { en = "Permanently adds $468358s1 Stamina, $468358s2 Intellect, and increases healing by up to $468358s3 to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.", description = "Aggiunge permanentemente $468358s1 alla Tempra, $468358s2 all'Intelletto e aumenta le cure fino a $468358s3 a un oggetto per gambe o testa. Non si cumula con altri incantamenti per lo slot equipaggiamento selezionato." },
    [468362] = { en = "Permanently adds $468361s1 Stamina, $468361s2 Defense, and $468361s3% chance to Block to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.", description = "Aggiunge permanentemente $468361s1 alla Tempra, $468361s2 alla Difesa e una probabilità di bloccare del $468361s3% a un oggetto per gambe o testa. Non si cumula con altri incantamenti per lo slot equipaggiamento selezionato." },
    [468365] = { en = "Permanently adds $468363s1 Stamina, $468363s2% chance to hit, and increases spell damage and healing by up to $468363s4 to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.", description = "Aggiunge permanentemente $468363s1 alla Tempra, una probabilità di colpire del $468363s2% e aumenta i danni magici e le cure fino a $468363s4 a un oggetto per gambe o testa. Non si cumula con altri incantamenti per lo slot equipaggiamento selezionato." },
    [468368] = { en = "Permanently adds $468367s1 Stamina, $468367s2% chance to hit, and $468367s4 Defense to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.", description = "Aggiunge permanentemente $468367s1 alla Tempra, una probabilità di colpire del $468367s2% e $468367s4 alla Difesa a un oggetto per gambe o testa. Non si cumula con altri incantamenti per lo slot equipaggiamento selezionato." },
    [468373] = { en = "Permanently adds $468372s1 Stamina, $468372s2 Strength, and $468372s3 Agility to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.", description = "Aggiunge permanentemente $468372s1 alla Tempra, $468372s2 alla Forza e $468372s3 all'Agilità a un oggetto per gambe o testa. Non si cumula con altri incantamenti per lo slot equipaggiamento selezionato." },
    [468376] = { en = "Permanently adds $468375s1 Stamina, $468375s2 Defense, and $468375s3 Shield Block value to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.", description = "Aggiunge permanentemente $468375s1 alla Tempra, $468375s2 alla Difesa e $468375s3 al valore di Blocco con Scudo a un oggetto per gambe o testa. Non si cumula con altri incantamenti per lo slot equipaggiamento selezionato." },
    [468380] = { en = "Permanently adds $468379s1 Stamina, $468379s2 Intellect, and increases spell damage and healing by up to $468379s3 to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.", description = "Aggiunge permanentemente $468379s1 alla Tempra, $468379s2 all'Intelletto e aumenta i danni magici e le cure fino a $468379s3 a un oggetto per gambe o testa. Non si cumula con altri incantamenti per lo slot equipaggiamento selezionato." },
    [468383] = { en = "Permanently adds $468382s1 Stamina, $468382s2 Agility, and $468382s3 Strength to a leg or head slot item. Does not stack with other enchantments for the selected equipment slot.", description = "Aggiunge permanentemente $468382s1 alla Tempra, $468382s2 all'Agilità e $468382s3 alla Forza a un oggetto per gambe o testa. Non si cumula con altri incantamenti per lo slot equipaggiamento selezionato." },
    [468387] = { en = "Aligns the Druid with nature, increasing the damage done by spells by $s1%, improving heal effects by $s2%, and increasing the critical strike chance of spells by $s3% for $d.", description = "Allinea il Druido con la natura, aumentando del $s1% i danni inflitti dagli incantesimi, migliorando del $s2% gli effetti curativi e aumentando del $s3% la probabilità di colpo critico degli incantesimi per $d." },
    [468388] = { en = "Your next $s2 Shots or melee abilities within $d do not incur a cooldown.", description = "I tuoi successivi $s2 Tiri o abilità in mischia entro $d non attivano un tempo di recupero." },
    [468458] = { en = "Instantly increases your energy by $s1. If Cutthroat is engraved, gain an activation of Cutthroat's Ambush effect.", description = "Aumenta istantaneamente la tua energia di $s1. Se Colpo di Grazia è inciso, ottieni un'attivazione dell'effetto Imboscata di Colpo di Grazia." },
    [468461] = { en = "Increases the critical hit chance of spells by $s1% for $d. If Shock and Awe is engraved, gain an additional $s2%.", description = "Aumenta del $s1% la probabilità di colpo critico degli incantesimi per $d. Se Shock e Sgomento è inciso, ottieni un ulteriore $s2%." },
    [468462] = { en = "Increases your shield block value by $s2 for $d1, and instantly increases your rage by $/10;s1.", description = "Aumenta il valore di parata con lo scudo di $s2 per $d1 e aumenta istantaneamente la tua rabbia di $/10;s1." },
    [468512] = { en = "Increases the critical hit chance of your Frostbolt, Spellfrost Bolt, and Frozen Orb spells by $s1%, and increases the critical hit damage of your Frostbolt, Spellfrost Bolt, and Frozen Orb spells by $s2% for $d.", description = "Aumenta del $s1% la probabilità di colpo critico degli incantesimi Dardo di Gelo, Dardo di Spellfrost e Globo Congelato e del $s2% i danni critici di questi incantesimi per $d." },
    [468531] = { en = "Reduces the casting time of your Greater Heal spells by $s1%, reduces the mana cost of your healing spells by $s2%, and casts of Penance on allies will target up to ${$s3-1} additional targets for $d.", description = "Riduce del $s1% il tempo di lancio degli incantesimi Guarigione Superiore, riduce del $s2% il costo in mana dei tuoi incantesimi di cura e lanciando Penitenza sugli alleati bersaglierai fino a ${$s3-1} bersagli aggiuntivi per $d." },
    [468540] = { en = "Increases your critical hit chance by $s1%, and increases your pet's attack speed by $468543s1% for $d. This spell does not affect temporary pets or Subjugated Demons.", description = "Aumenta del $s1% la tua probabilità di colpo critico e aumenta la velocità d'attacco del tuo famiglio del $468543s1% per $d. Questo incantesimo non ha effetto sui famigli temporanei o sui Demoni Soggiogati." },
    [468758] = { en = "Increases healing done by spells and effects by up to $s1. This effect is not cumulative with other ring runes.", description = "Aumenta le cure fornite da incantesimi ed effetti fino a $s1. Questo effetto non è cumulabile con altre rune per anelli." },
    [468761] = { en = "Engrave your ring with the Healing Specialization rune:\r\n\r\n$@spellicon468758\r\n$@spelldesc468758", description = "Incidi sul tuo anello la runa della Specializzazione in Guarigione:\r\n\r\n$@spellicon468758\r\n$@spelldesc468758" },
    [468762] = { en = "Restores $s1 mana per 5 sec. This effect is not cumulative with other ring runes.", description = "Ripristina $s1 mana ogni 5 s. Questo effetto non è cumulabile con altre rune per anelli." },
    [468763] = { en = "Engrave your ring with the Meditation Specialization rune:\r\n\r\n$@spellicon468762\r\n$@spelldesc468762", description = "Incidi sul tuo anello la runa della Specializzazione in Meditazione:\r\n\r\n$@spellicon468762\r\n$@spelldesc468762" },
    [468769] = { en = "Reflects Nature spells back at their caster for $d.", description = "Riflette gli incantesimi della Natura sul loro incantatore per $d." },
    [468784] = { en = "Increases your Arcane and Shadow spell damage by up to $s1 for $d.", description = "Aumenta i danni dei tuoi incantesimi Arcani e dell'Ombra fino a $s1 per $d." },
    [468785] = { en = "Increases damage done by Shadow and Arcane spells and effects by up to $s1.", description = "Aumenta i danni inflitti da incantesimi ed effetti dell'Ombra e Arcani fino a $s1." },
    [468843] = { en = "Bleeding for $s2 damage every second.", description = "Sanguina, subendo $s2 danni ogni secondo." },
    [468913] = { en = "Increase the range of your Holy Shock spell by $s1 yards, but reduces all Holy damage you deal by $s2%.", description = "Aumenta di $s1 metri la portata del tuo incantesimo Folgore Sacra, ma riduce del $s2% tutti i danni Sacri che infliggi." },
    [468925] = { en = "Move speed slowed by $s2%.", description = "Velocità di movimento ridotta del $s2%." },
    [469055] = { en = "Launches a barrage of Fire at the enemy, causing $7268s1  Fire damage each second for $d.", description = "Scaglia una raffica di Fuoco contro il nemico, infliggendo $7268s1  danni da Fuoco ogni secondo per $d." },
    [469056] = { en = "Launches a barrage of Frost at the enemy, causing $7268s1  Frost damage each second for $d.", description = "Scaglia una raffica di Gelo contro il nemico, infliggendo $7268s1  danni da Gelo ogni secondo per $d." },
    [469057] = { en = "Launches a barrage of Earth at the enemy, causing $7268s1  Nature damage each second for $d.", description = "Scaglia una raffica di Terra contro il nemico, infliggendo $7268s1  danni da Natura ogni secondo per $d." },
    [469058] = { en = "Launches a barrage of Lightning at the enemy, causing $7268s1  Nature damage each second for $d.", description = "Scaglia una raffica di Fulmini contro il nemico, infliggendo $7268s1  danni da Natura ogni secondo per $d." },
    [469105] = { en = "Spits corrupted blood, inflicting $469114s1 Shadow damage every $469110t1 sec. This has a chance to spread to nearby players.", description = "Sputa sangue corrotto, infliggendo $469114s1 danni da Ombra ogni $469110t1 s. Ha una probabilità di diffondersi ai giocatori vicini." },
    [469110] = { en = "$@spelldesc469105", description = "$@spelldesc469105" },
    [469114] = { en = "$@spelldesc469105", description = "$@spelldesc469105" },
    [469115] = { en = "$@spelldesc469105", description = "$@spelldesc469105" },
    [469128] = { en = "Combine with two other pieces to form the Sigil of the Keeper.", description = "Combina con altri due pezzi per formare il Sigillo del Custode." },
    [469145] = { en = "The hunter takes on the aspects of a Falcon, increasing melee and ranged Attack Power by the same amount as their highest rank of Aspect of the Hawk.\r\n\r\nWhile Aspect of the Falcon is active, the Improved Aspect of the Hawk talent can now proc from and benefit melee attacks.  Only one Aspect can be active at a time.", description = "Il cacciatore assume le sembianze di un falco, aumentando la potenza d'attacco in mischia e a distanza della stessa quantità garantita dal grado più alto di Aspetto del Falco.\r\n\r\nFinché Aspetto del Falco è attivo, il talento Aspetto del Falco Migliorato può attivarsi dagli attacchi in mischia e potenziarli.  Può essere attivo un solo Aspetto alla volta." },
    [469191] = { en = "Read a prophecy from the tome, granting $s1% increased critical strike chance for your next non-periodic spell or attack.", description = "Leggi una profezia dal tomo, ottenendo un aumento del $s1% alla probabilità di colpo critico per il prossimo incantesimo o attacco non periodico." },
    [469208] = { en = "Critical effect chance increased by $s1%.", description = "Probabilità di effetto critico aumentata del $s1%." },
    [469210] = { en = "Healing done increased by up to $s1.", description = "Cure fornite aumentate fino a $s1." },
    [469211] = { en = "Chance on direct damage spell to cause your next pet summoned within $469220d1 to be instant cast and not consume a Soul Shard.", description = "Quando infliggi danni con un incantesimo diretto, hai una probabilità di rendere istantaneo il prossimo famiglio evocato entro $469220d1, senza consumare una Scheggia d'Anima." },
    [469220] = { en = "Your next Imp, Voidwalker, Succubus, Incubus, Felhunter, or Felguard Summon spell has its casting time reduced by $/1000;s1 sec, and does not cost a Soul Shard or Mana.", description = "Il tempo di lancio del tuo prossimo incantesimo Evocazione di Imp, Camminatore del Vuoto, Succube, Incubo, Vilcacciatore o Vilguardia è ridotto di $/1000;s1 s e non costa una Scheggia d'Anima né mana." },
    [469221] = { en = "Harvest the soul of your summoned demon, granting you an effect that lasts $469224d.  The effect is canceled if any Demon is summoned.", description = "Raccogli l'anima del tuo demone evocato, ottenendo un effetto che dura $469224d.  L'effetto si annulla se viene evocato un Demone." },
    [469229] = { en = "Your next Curse of Tongues cast will silence the target for $469227d1. If used on a casting target, it will counter the enemy's spellcast, preventing any spell from that school of magic from being cast for $469228d1.", description = "Il tuo prossimo lancio di Maledizione delle Lingue silenzierà il bersaglio per $469227d1. Se usato su un bersaglio che sta lanciando un incantesimo, interromperà il lancio nemico, impedendo di lanciare incantesimi di quella scuola di magia per $469228d1." },
    [469230] = { en = "Physical damage taken reduced by $s1%, and your Demon Charge ability is now usable while in combat and has no cooldown.", description = "Danni fisici subiti ridotti del $s1%; la tua abilità Carica Demoniaca è ora utilizzabile durante il combattimento e non ha tempo di recupero." },
    [469237] = { en = "When Improved Scorch is talented, targets hit by your Blast Wave will also have $s1 stacks of Fire Vulnerability applied to them.", description = "Quando hai appreso il talento Bruciatura Migliorata, i bersagli colpiti dalla tua Onda d'Urto subiranno anche $s1 accumuli di Vulnerabilità al Fuoco." },
    [469238] = { en = "While Ice Barrier is active the damage done by Frost spells and effects is increased by up to $s1.", description = "Finché Barriera di Ghiaccio è attiva, i danni inflitti da incantesimi ed effetti del Gelo aumentano fino a $s1." },
    [469320] = { en = "You hurl molten lava at the target, dealing ${$m1/100*$<damagepower>} to ${$M1/100*$<damagepower>} Fire damage. If your Flame Shock is on the target, Lava Burst will deal a critical strike.", description = "Scagli lava fusa contro il bersaglio, infliggendo da ${$m1/100*$<damagepower>} a ${$M1/100*$<damagepower>} danni da Fuoco. Se il bersaglio è affetto da Folgore di Fuoco, Eruzione di Lava infligge un colpo critico." },
    [469647] = { en = "Apply the Blood of the Lightbringer to consecrate your weapon.", description = "Applica il Sangue del Portatore di Luce per consacrare la tua arma." },
    [470037] = { en = "Attune with the fires within, allowing you to replace your Cat form with a more fiery visage.", description = "Ti sintonizzi con i fuochi interiori, potendo sostituire la forma felina con un aspetto più fiammeggiante." },
    [470078] = { en = "Your Crusader Strike spell restores an additional $s1% of your maximum mana.", description = "Il tuo incantesimo Assalto del Crociato ripristina un ulteriore $s1% del tuo mana massimo." },
    [470081] = { en = "While a Shield is equipped, your melee attacks with Rockbiter Weapon trigger your Maelstrom Weapon rune $470082s1% more often.", description = "Con uno scudo equipaggiato, i tuoi attacchi in mischia con Arma Rocciadura attivano la tua runa Arma del Maelstrom con una frequenza superiore del $470082s1%." },
    [470082] = { en = "Increases the frequency of Maelstrom Weapon triggering by $s1%.", description = "Aumenta del $s1% la frequenza di attivazione di Arma del Maelstrom." },
    [470104] = { en = "While Rolling Thunder is engraved, Lava Burst casts have a $s1% chance to add an additional charge to your active Lightning Shield.", description = "Con la runa Tuono Rotolante incisa, i lanci di Eruzione di Lava hanno una probabilità del $s1% di aggiungere una carica aggiuntiva al tuo Scudo di Fulmini attivo." },
    [470105] = { en = "Your Elemental Focus talent now has a maximum of ${$s1+1} charges, and is set to ${$s1+1} charges when it triggers.", description = "Il tuo talento Focalizzazione Elementale ora può avere al massimo ${$s1+1} cariche e viene impostato a ${$s1+1} cariche quando si attiva." },
    [470108] = { en = "You turn to stone, protecting you from all physical attacks and spells for $d, but during that time you cannot attack, move or cast spells.  You can only have the effect of one flask at a time.", description = "Ti trasformi in pietra, proteggendoti da tutti gli attacchi fisici e dagli incantesimi per $d, ma durante questo periodo non puoi attaccare, muoverti o lanciare incantesimi.  Puoi beneficiare dell'effetto di una sola fiasca alla volta." },
    [470235] = { en = "Increases the attack power bonus on Windfury Weapon attacks by $s1.", description = "Aumenta di $s1 il bonus alla potenza d'attacco degli attacchi con Arma del Vento Furente." },
    [470240] = { en = "While Frostbrand Weapon is active on your main hand weapon, your Water Shield triggers reduce the cast time of your next Chain Lightning spell within $470272d1 by $470272s1%, and increases its damage by $470272s1%. Stacking up to 5 times.", description = "Finché Arma del Gelo è attiva sull'arma nella mano principale, le attivazioni di Scudo d'Acqua riducono del $470272s1% il tempo di lancio del tuo prossimo Catena di Fulmini entro $470272d1 e ne aumentano i danni del $470272s1%. Si accumula fino a 5 volte." },
    [470246] = { en = "Causing damage with your Holy Shock spell reduces the cast time and mana cost of your next Holy Wrath cast within $470271d1 by $470271s1%, and increases its damage by $470271s4%. Stacking up to 5 times.", description = "Infliggere danni con il tuo incantesimo Folgore Sacra riduce del $470271s1% il tempo di lancio e il costo in mana del tuo prossimo lancio di Ira Sacra entro $470271d1 e ne aumenta i danni del $470271s4%. Si accumula fino a 5 volte." },
    [470263] = { en = "Your Avenger's Shield hits $s2 fewer targets, but will hit its target $s1 times.", description = "Lo Scudo del Vendicatore colpisce $s2 bersagli in meno, ma colpisce il suo bersaglio $s1 volte." },
    [470265] = { en = "Hurls a holy shield at the enemy, dealing ${$m1*$<damagepower>/100+0.091*$SPH+0.091*$AP} to ${$M1*$<damagepower>/100+0.091*$SPH+0.091*$AP} Holy damage, Dazing them and then jumping to additional nearby enemies.  Affects $x1 total targets.  Lasts $d.", description = "Scagli uno scudo sacro contro il nemico, infliggendo da ${$m1*$<damagepower>/100+0.091*$SPH+0.091*$AP} a ${$M1*$<damagepower>/100+0.091*$SPH+0.091*$AP} danni Sacri, stordendolo e poi rimbalzando sui nemici vicini.  Colpisce $x1 bersagli in totale.  Dura $d." },
    [470266] = { en = "Increases healing done by Nourish by up to $s1.", description = "Aumenta le cure fornite da Nutrimento fino a $s1." },
    [470788] = { en = "Chance to hit with Frost spells increased by $s1%. Not cumulative with other ring runes.", description = "Probabilità di colpire con incantesimi del Gelo aumentata del $s1%. Non cumulabile con altre rune per anelli." },
    [470789] = { en = "Chance to hit with Fire spells increased by $s1%. Not cumulative with other ring runes.", description = "Probabilità di colpire con incantesimi del Fuoco aumentata del $s1%. Non cumulabile con altre rune per anelli." },
    [471401] = { en = "While applied to target shield it increases spell damage and healing by up to 36 and increases Spell Critical chance by 1%.  Lasts for 30 minutes.", description = "Se applicato allo scudo del bersaglio, aumenta i danni degli incantesimi e le cure fino a 36 e aumenta dell'1% la probabilità di colpo critico degli incantesimi.  Dura 30 minuti." },
    [471698] = { en = "Attune with the darkness within, allowing you better control over your inner demon.", description = "Sintonizzati con l'oscurità interiore, ottenendo un maggiore controllo sul tuo demone interiore." },
    [471699] = { en = "Attune to the darkness within, allowing you better control over your inner demon.\r\n", description = "Sintonizzati con l'oscurità interiore, ottenendo un maggiore controllo sul tuo demone interiore.\r\n" },
    [473387] = { en = "Rally your nearby party or raid members, granting them $s1% increased spell critical strike chance, $s3% increased melee and ranged critical strike chance, and $s2 increased attack power. Lasts $d. Exclusive with similar world effects and unaffected by Chronoboons.", description = "Raduna i membri vicini del tuo gruppo o della tua incursione, aumentando la loro probabilità di critico con gli incantesimi del $s1%, la probabilità di critico in mischia e a distanza del $s3% e la potenza d'attacco di $s2. Dura $d. Esclusivo con effetti del mondo simili e non influenzato dai Cronoboon." },
    [473399] = { en = "Summon a songflower that grants all your party or raid members $s1% increased chance for a melee, ranged, or spell critical by and $s2 increased attributes by for $d. Exclusive with similar world effects. Unaffected by Chronoboons.", description = "Evoca un fiore cantore che aumenta per $d la probabilità di critico in mischia, a distanza o con gli incantesimi di tutti i membri del tuo gruppo o della tua incursione del $s1% e i loro attributi di $s2. Esclusivo con effetti del mondo simili. Non influenzato dai Cronoboon." },
    [473403] = { en = "Grants all your nearby party or raid members $s1 increased attack power, $s3% increased Stamina, and $s4% increased spell critical strike chance for $d. Exclusive with similar world effects. Unaffected by Chronoboons.", description = "Aumenta la potenza d'attacco di tutti i membri vicini del tuo gruppo o della tua incursione di $s1, la Tempra del $s3% e la probabilità di critico con gli incantesimi del $s4% per $d. Esclusivo con effetti del mondo simili. Non influenzato dai Cronoboon." },
    [473441] = { en = "Increases hitpoints by $s1. $s2% haste to melee attacks. $s3 mana regen every 5 seconds.", description = "Aumenta i punti vita di $s1. $s2% di celerità agli attacchi in mischia. $s3 di rigenerazione del mana ogni 5 secondi." },
    [473450] = { en = "Grants all your party or raid members $s1% increased damage done for $d.", description = "Aumenta i danni inflitti da tutti i membri del tuo gruppo o della tua incursione del $s1% per $d." },
    [473466] = { en = "Summon a cauldron of Firewater for $d, useable by all members of your party or raid to increase melee attack power by $473469s1 and size for $473469d.", description = "Evoca un calderone di Acquafuoco per $d, utilizzabile da tutti i membri del tuo gruppo o della tua incursione per aumentare la potenza d'attacco in mischia di $473469s1 e la taglia per $473469d." },
    [473476] = { en = "Grants all your party or raid members $s1% increased movement speed and $s3% increased stats for $d.", description = "Aumenta la velocità di movimento di tutti i membri del tuo gruppo o della tua incursione del $s1% e le statistiche del $s3% per $d." },
    [473493] = { en = "Place a trap at a nearby location that explodes when a Silithid from Hive'Ashi, Hive'Regal, or Hive'Zora approaches, causing the Silithid to take $473496s1% of its health in damage every $473496t sec for $473496d.", description = "Piazza una trappola in una posizione vicina che esplode quando un Silitide di Alveare'Ashi, Alveare'Regal o Alveare'Zora si avvicina, infliggendo al Silitide danni pari al $473496s1% della sua salute ogni $473496t sec per $473496d." },
    [473525] = { en = "Freezes a Silithid within the Hive'Ashi, Hive'Regal, or Hive'Zora hives for $d. Effect broken by any damage.", description = "Congela un Silitide all'interno degli alveari di Alveare'Ashi, Alveare'Regal o Alveare'Zora per $d. L'effetto viene interrotto da qualsiasi danno." },
    [473544] = { en = "Inhaling this incense causes you to fade into the shadows, allowing you to sneak around while inside Hive'Ashi, Hive'Regal, or Hive'Zora, but reduces your speed by $s2%.  Lasts $d.", description = "Inalare questo incenso ti fa svanire nelle ombre, consentendoti di muoverti furtivamente all'interno di Alveare'Ashi, Alveare'Regal o Alveare'Zora, ma riduce la tua velocità del $s2%.  Dura $d." },
    [473561] = { en = "Throw the ancient rope to restrain a silithid of Hive'Ashi, Hive'Regal, or Hive'Zora and pull them toward you. May not be used on enemies higher than level ${$PL+1} or which are marked as boss enemies.", description = "Lancia la corda antica per trattenere un silitide di Alveare'Ashi, Alveare'Regal o Alveare'Zora e tirarlo verso di te. Non può essere usata sui nemici di livello superiore a ${$PL+1} o contrassegnati come boss." },
    [474127] = { en = "Your damaging non-periodic Nature spell critical strikes have a chance to grant you $474126s1 increased spell damage for $474126d1.", description = "I tuoi colpi critici con incantesimi della Natura che infliggono danni non periodici hanno una probabilità di conferirti $474126s1 di danni degli incantesimi aggiuntivi per $474126d1." },
    [474142] = { en = "Your damaging non-periodic spells increase your spell damage by $474148s1 for $474148d1.  If the target is player controlled, gain $474146s2 spell penetration for $474146d1 instead.", description = "I tuoi incantesimi che infliggono danni aumentano i danni degli incantesimi di $474148s1 per $474148d1.  Se il bersaglio è controllato da un giocatore, ottieni invece $474146s2 di penetrazione degli incantesimi per $474146d1." },
    [474196] = { en = "Your damaging spell casts have a chance to summon Visions of the Qiraji Prophets.", description = "Il lancio dei tuoi incantesimi che infliggono danni ha una probabilità di evocare Visioni dei Profeti Qiraji." },
    [474564] = { en = "Thunderclap.", description = "Tuono." },
    [474565] = { en = "Shadowbolt.", description = "Dardo d'ombra." },
    [474570] = { en = "Fire.", description = "Fuoco." },
    [474571] = { en = "Plague.", description = "Piaga." },
    [1213145] = { en = "Perform an ancient Qiraji ceremony.", description = "Esegui un'antica cerimonia Qiraji." },
    [1213234] = { en = "Briefly recompose your body, causing you to immediately remove all active poison effects and gain immunity to all Nature damage for $d.", description = "Ricomponi brevemente il tuo corpo, rimuovendo immediatamente tutti gli effetti di veleno attivi e ottenendo immunità a tutti i danni della Natura per $d." },
    [1213238] = { en = "Your damaging non-periodic spells increase your spell damage by $1213241s1 for $1213241d1.  If the target is player controlled, gain $1213240s1 spell penetration for $1213240d1 instead.", description = "I tuoi incantesimi che infliggono danni aumentano i danni degli incantesimi di $1213241s1 per $1213241d1.  Se il bersaglio è controllato da un giocatore, ottieni invece $1213240s1 di penetrazione degli incantesimi per $1213240d1." },
    [1213278] = { en = "Instantly shields you, absorbing $s1 damage.  Lasts $d.  While the shield holds, spells will not be interrupted.\r\n", description = "Ti protegge istantaneamente, assorbendo $s1 danni.  Dura $d.  Finché lo scudo regge, gli incantesimi non verranno interrotti.\r\n" },
    [1213335] = { en = "Burrow into the ground, turning yourself untargetable for $d1.", description = "Scava nel terreno, rendendoti non selezionabile per $d1." },
    [1213390] = { en = "Gives you $s1% chance per piece of Timeworn armor equipped to get an extra attack on melee or ranged hit.", description = "Ti conferisce una probabilità del $s1% per ogni pezzo di armatura del Tempo consunta equipaggiato di effettuare un attacco aggiuntivo con un colpo in mischia o a distanza." },
    [1213398] = { en = "Increases the casting speed of your spells by $s1% per piece of Timeworn armor equipped.", description = "Aumenta la velocità di lancio dei tuoi incantesimi del $s1% per ogni pezzo di armatura del Tempo consunta equipaggiato." },
    [1213405] = { en = "Increases the effectiveness of your healing and shielding spells by $s1% per piece of Timeworn armor equipped.", description = "Aumenta l'efficacia dei tuoi incantesimi di cura e assorbimento del $s1% per ogni pezzo di armatura del Tempo consunta equipaggiato." },
    [1213407] = { en = "Reduces the chance for your attacks to be dodged or parried by $s1% per piece of Timeworn armor equipped.", description = "Riduce la probabilità che i tuoi attacchi vengano schivati o parati del $s1% per ogni pezzo di armatura del Tempo consunta equipaggiato." },
    [1213616] = { en = "Permanently enchant a piece of chest armor to increase all stats by 4, and Nature Resistance by 15.", description = "Incanta permanentemente un pezzo di armatura per il torso, aumentando tutte le statistiche di 4 e la resistenza alla Natura di 15." },
    [1213619] = { en = "Increases damage done by holy spells and effects by up to $s1.", description = "Aumenta i danni inflitti dagli incantesimi e dagli effetti sacri fino a $s1." },
    [1213622] = { en = "Permanently enchant gloves to increase holy damage by up to 20.", description = "Incanta permanentemente i guanti per aumentare i danni sacri fino a 20." },
    [1213625] = { en = "Increases damage done by arcane spells and effects by up to $s1.", description = "Aumenta i danni inflitti dagli incantesimi e dagli effetti arcani fino a $s1." },
    [1213626] = { en = "Permanently enchant gloves to increase arcane damage by up to 20.", description = "Incanta permanentemente i guanti per aumentare i danni arcani fino a 20." },
    [1213829] = { en = "Permanently increase the spell damage and healing of an item worn on the chest, legs, hands or feet by up to 10.  Only usable on items level 45 and above.", description = "Aumenta permanentemente fino a 10 i danni degli incantesimi e le cure di un oggetto indossato sul torso, sulle gambe, sulle mani o sui piedi.  Utilizzabile solo su oggetti di livello 45 o superiore." },
    [1213833] = { en = "Permanently cause an item worn on the chest, legs, hands or feet to cause 20 Nature damage to the attacker when struck in combat.  Only usable on items level 45 and above.", description = "Fa sì permanentemente che un oggetto indossato sul torso, sulle gambe, sulle mani o sui piedi infligga 20 danni della Natura all'attaccante quando si viene colpiti in combattimento.  Utilizzabile solo su oggetti di livello 45 o superiore." },
    [1213904] = { en = "Increases Agility by $s1, chance to get a critical hit by $s2%, and Nature Resistance by $s3 for $d.", description = "Aumenta l'Agilità di $s1, la probabilità di mettere a segno un colpo critico del $s2% e la resistenza alla Natura di $s3 per $d." },
    [1213914] = { en = "Increases spell damage by up to $s1 and Nature Resistance by $s2 for $d.", description = "Aumenta i danni degli incantesimi fino a $s1 e la resistenza alla Natura di $s2 per $d." },
    [1213917] = { en = "Increases armor by $s1, defense value by $s2, and Nature Resistance by $s3 for $d.", description = "Aumenta l'armatura di $s1, il valore di difesa di $s2 e la resistenza alla Natura di $s3 per $d." },
    [1213922] = { en = "Increases the player's run speed by $s1% for $d.", description = "Aumenta la velocità di corsa del giocatore del $s1% per $d." },
    [1214004] = { en = "While applied to target weapon or shield it increases spell damage by up to $1214006s1 and increases Spell Critical chance by $1214006s3% .  Lasts for 30 minutes.", description = "Quando applicato all'arma o allo scudo bersaglio, aumenta i danni degli incantesimi fino a $1214006s1 e la probabilità di critico con gli incantesimi del $1214006s3% .  Dura 30 minuti." },
    [1214058] = { en = "Increases the amount healed by your Holy Light and Flash of Light spells by $s1%.", description = "Aumenta le cure dei tuoi incantesimi di Luce sacra e Lampo di luce del $s1%." },
    [1214059] = { en = "Increases the amount healed by your Chain Heal and Healing Wave spells by $s1%.", description = "Aumenta le cure dei tuoi incantesimi di Catena di guarigione e Ondata di guarigione del $s1%." },
    [1214063] = { en = "Increases the amount healed by your Lifebloom, Nourish, and Wild Growth spells by $s1%.", description = "Aumenta le cure dei tuoi incantesimi di Fioritura vitale, Nutrizione e Crescita selvaggia del $s1%." },
    [1214070] = { en = "Reduces all incoming damage by $s1. ", description = "Riduce tutti i danni subiti di $s1. " },
    [1214125] = { en = "Chance on direct spell damage or melee attack to deal $1213941s1 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit.", description = "Probabilità, con i danni diretti degli incantesimi o gli attacchi in mischia, di infliggere $1213941s1 danni da Fuoco al bersaglio. Infligge danni aggiuntivi alle creature Silitidi a Silitus con quasi ogni colpo." },
    [1214136] = { en = "After $d, deals heavy damage that's split among everyone affected.", description = "Dopo $d, infligge ingenti danni suddivisi tra tutti i bersagli colpiti." },
    [1214155] = { en = "Increases the damage dealt by all of your damage over time spells by $s1% per piece of Timeworn armor equipped.", description = "Aumenta i danni inflitti da tutti i tuoi incantesimi di danno periodico del $s1% per ogni pezzo di armatura del Tempo consunta equipaggiato." },
    [1214168] = { en = "Coats a weapon with poison that lasts for 30 minutes.\r\nEach strike has a 30% chance of poisoning the enemy for $1214170o1 Nature damage over $1214170d and causing the enemy to take $1214170s2% increased Arcane, Fire, Frost, Nature, and Shadow damage.  Stacks up to $1214170u times on a single target.\r\n\r\nOccult Poison counts as Deadly Poison and benefits from all talents and effects that trigger from or modify Deadly Poison.", description = "Ricopre un'arma di veleno che dura 30 minuti.\r\nOgni colpo ha una probabilità del 30% di avvelenare il nemico, infliggendo $1214170o1 danni della Natura in $1214170d e facendo subire al nemico il $1214170s2% di danni arcani, da Fuoco, da Gelo, della Natura e dell'Ombra aggiuntivi.  Si accumula fino a $1214170u volte sullo stesso bersaglio.\r\n\r\nIl Veleno occulto conta come Veleno mortale e beneficia di tutti i talenti e gli effetti che si attivano con Veleno mortale o lo modificano." },
    [1214169] = { en = "Teaches Occult Poison (Rank 2).", description = "Insegna Veleno occulto (grado 2)." },
    [1214171] = { en = "Coats a weapon with poison that lasts for 30 minutes. Each strike has a $h% chance of poisoning the enemy for $1214170o1 Nature damage over $1214170d and causing the enemy to take $1214170s2% increased Arcane, Fire, Frost, Nature, and Shadow damage.  Stacks up to $1214170u times on a single target.\r\n\r\nOccult Poison counts as Deadly Poison and benefits from all talents and effects that trigger from or modify Deadly Poison.\r\n", description = "Riveste un'arma di veleno che dura 30 minuti. Ogni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo $1214170o1 danni Natura nell'arco di $1214170d e facendo subire al nemico il $1214170s2% di danni Arcano, Fuoco, Gelo, Natura e Ombra in più. Si accumula fino a $1214170u volte su un singolo bersaglio.\r\n\r\nVeleno Occulto conta come Veleno Mortale e beneficia di tutti i talenti e gli effetti che si attivano con Veleno Mortale o lo modificano.\r\n" },
    [1214285] = { en = "Increases the damage of Ferocious Bite and Shred by $s1%.", description = "Aumenta i danni di Morso Feroce e Dilaniamento del $s1%." },
    [1214286] = { en = "Increases the damage of Swipe and Mangle by $s1%.", description = "Aumenta i danni di Spazzata e Macellazione del $s1%." },
    [1214295] = { en = "Increases the damage of Moonfire and Wrath by $s1%.", description = "Aumenta i danni di Fuoco Lunare e Ira del $s1%." },
    [1214296] = { en = "Increases the damage of Exorcism and Crusader Strike by $s1%.", description = "Aumenta i danni di Esorcismo e Assalto del Crociato del $s1%." },
    [1214297] = { en = "Increases the damage of Holy Shock by $s1%, and your Shock and Awe buff now also grants $1214298s1% increased Holy Damage. (This effect does not stack with Sanctity Aura).", description = "Aumenta i danni di Sacro Shock del $s1% e il tuo potenziamento Shock e Stupore ora fornisce anche il $1214298s1% di danni Sacri in più. (Questo effetto non si cumula con Aura di Santità)." },
    [1214298] = { en = "Increases Holy damage done by $s1%. ", description = "Aumenta i danni Sacri inflitti del $s1%. " },
    [1214299] = { en = "Increases the damage of Hammer of the Righteous and Shield of Righteousness by $s1%.", description = "Aumenta i danni di Martello del Giusto e Scudo della Rettitudine del $s1%." },
    [1214300] = { en = "Increases the damage of Stormstrike and Windfury Weapon by $s1%.", description = "Aumenta i danni di Assalto della Tempesta e Arma del Furore del Vento del $s1%." },
    [1214301] = { en = "Increases the damage of Flame Shock and Molten Blast by $s1%.", description = "Aumenta i danni di Shock di Fiamma e Esplosione Fusa del $s1%." },
    [1214302] = { en = "Increases the damage of Lightning Bolt, Chain Lightning, and Lava Burst by $s1%.", description = "Aumenta i danni di Dardo Fulminante, Catena di Fulmini e Esplosione di Lava del $s1%." },
    [1214777] = { en = "Sends out a blast wave of magic, inflicting $s1 Arcane damage to nearby enemies.\r\n", description = "Scatena un'ondata di magia che infligge $s1 danni Arcani ai nemici vicini.\r\n" },
    [1215380] = { en = "Summons and dismisses a rideable Raptor.  This is a very fast mount.", description = "Evoca e congeda un Raptor cavalcabile. È una cavalcatura molto veloce." },
    [1215404] = { en = "While Metamorphosis or Way of Earth is active, increases the effectiveness of your Fire damage spells by $s1% per piece of Timeworn armor equipped.", description = "Quando Metamorfosi o Via della Terra è attiva, aumenta l'efficacia dei tuoi incantesimi di danno da Fuoco del $s1% per ogni pezzo di armatura Logora dal Tempo equipaggiato." },
    [1216026] = { en = "Transmute 100 Blood-Caked Silver Coins into 1 Blood-Caked Gold Coin.", description = "Trasforma 100 monete d'argento macchiate di sangue in 1 moneta d'oro macchiata di sangue." },
    [1216027] = { en = "Transmute 100 Blood-Caked Copper Coins into 1 Blood-Caked Silver Coin.", description = "Trasforma 100 monete di rame macchiate di sangue in 1 moneta d'argento macchiata di sangue." },
    [1216997] = { en = "Reduces all damage taken from players and their pets by $s2%. This effect cannot be combined from multiple sources.", description = "Riduce tutti i danni subiti dai giocatori e dai loro famigli del $s2%. Questo effetto non può essere combinato da più fonti." },
    [1217189] = { en = "Permanently enchant bracers to add up to 12 damage to spells.", description = "Incanta permanentemente i bracciali per aggiungere fino a 12 danni agli incantesimi." },
    [1217203] = { en = "Permanently enchant bracers to increase Agility by 9.", description = "Incanta permanentemente i bracciali per aumentare l'Agilità di 9." },
    [1217775] = { en = "Deals Fire damage every $t seconds.", description = "Infligge danni da Fuoco ogni $t secondi." },
    [1218071] = { en = "Summon a songflower that grants all your party or raid members $s1% increased chance for a melee, ranged, or spell critical and $s2 increased attributes for $473399d. Exclusive with similar world effects. Unaffected by Chronoboons.", description = "Evoca un fiore canoro che fornisce a tutti i membri del gruppo o dell'incursione il $s1% di probabilità in più di infliggere un colpo critico in mischia, a distanza o con incantesimi e $s2 agli attributi per $473399d. Esclusivo con effetti del mondo simili. Non influenzato dai Cronoboon." },
    [1218072] = { en = "Grants all your nearby party or raid members $s1 increased attack power, $s3% increased Stamina, and $s4% increased spell critical strike chance for $473403d. Exclusive with similar world effects. Unaffected by Chronoboons.", description = "Fornisce a tutti i membri del gruppo o dell'incursione vicini $s1 potenza d'attacco in più, il $s3% di Tempra in più e il $s4% di probabilità in più di infliggere un colpo critico con incantesimi per $473403d. Esclusivo con effetti del mondo simili. Non influenzato dai Cronoboon." },
    [1218073] = { en = "Grants all your party or raid members $s1% increased damage done for $473450d.", description = "Fornisce a tutti i membri del gruppo o dell'incursione il $s1% di danni inflitti in più per $473450d." },
    [1218074] = { en = "Increases hitpoints by $s1. $s2% haste to melee attacks. $s3 mana regen every 5 seconds. Lasts $473441d.", description = "Aumenta i punti vita di $s1. $s2% di celerità agli attacchi in mischia. $s3 rigenerazione di mana ogni 5 secondi. Dura $473441d." },
    [1218075] = { en = "Grants all your party or raid members $s1% increased movement speed and $s3% increased stats for $473476d.", description = "Fornisce a tutti i membri del gruppo o dell'incursione il $s1% di velocità di movimento in più e il $s3% alle statistiche in più per $473476d." },
    [1218121] = { en = "Rally your nearby party or raid members, granting them $s1% increased spell critical strike chance, $s3% increased melee and ranged critical strike chance, and $s2 increased attack power. Lasts $473387d. Exclusive with similar world effects and unaffected by Chronoboons.", description = "Sprona i membri vicini del gruppo o dell'incursione, fornendo loro il $s1% di probabilità in più di infliggere un colpo critico con incantesimi, il $s3% di probabilità in più di infliggere un colpo critico in mischia e a distanza e $s2 potenza d'attacco. Dura $473387d. Esclusivo con effetti del mondo simili e non influenzato dai Cronoboon." },
    [1218352] = { en = "Gives your Frost damage spells a $h% chance to apply the Winter's Chill effect, which increases the chance a Frost spell will critically hit the target by $12579s1% for $12579d.  Stacks up to $12579u times.", description = "I tuoi incantesimi di danno da Gelo hanno una probabilità del $h% di applicare l'effetto Brivido d'Inverno, che aumenta del $12579s1% la probabilità che un incantesimo di Gelo infligga un colpo critico al bersaglio per $12579d. Si accumula fino a $12579u volte." },
    [1218358] = { en = "Send the target into a rabid frenzy, increasing melee attack power by $s1 but reducing armor by $s2 for $d.  Rabid enemies will not flee and will ignore Fear and Horror effects.", description = "Fa cadere il bersaglio in una frenesia rabbiosa, aumentando la potenza d'attacco in mischia di $s1 ma riducendo l'armatura di $s2 per $d. I nemici rabbiosi non fuggono e ignorano gli effetti di Paura e Terrore." },
    [1219019] = { en = "Periodic shadow effects have a chance to apply Creeping Darkness up to $1219020U times. Spells which deal direct Shadow damage detonate this effect, dealing $M1 damage per stack.", description = "Gli effetti periodici d'Ombra hanno una probabilità di applicare Oscurità Strisciante fino a $1219020U volte. Gli incantesimi che infliggono danni diretti da Ombra fanno detonare questo effetto, infliggendo $M1 danni per accumulo." },
    [1219020] = { en = "$@spelldesc1219019", description = "$@spelldesc1219019" },
    [1219024] = { en = "$@spelldesc1219019", description = "$@spelldesc1219019" },
    [1219043] = { en = "Smash the corpse of a fallen friend or foe, dealing $s1 damage to nearby enemies.", description = "Colpisce il cadavere di un amico o nemico caduto, infliggendo $s1 danni ai nemici vicini." },
    [1219057] = { en = "$@spelldesc1219043", description = "$@spelldesc1219043" },
    [1219072] = { en = "Increases healing by $s2% and damage dealt by $s1%.", description = "Aumenta le cure del $s2% e i danni inflitti del $s1%." },
    [1219073] = { en = "The damage dealt by Creeping Darkness is increased by $s1%.", description = "I danni inflitti da Oscurità Strisciante aumentano del $s1%." },
    [1219083] = { en = "Deal $s1 Shadow damage to melee attackers. Causes twice as much threat as damage dealt.", description = "Infligge $s1 danni d'Ombra agli attaccanti in mischia. Genera il doppio della minaccia rispetto ai danni inflitti." },
    [1219090] = { en = "Silence the target for $d.", description = "Silenzia il bersaglio per $d." },
    [1219093] = { en = "Seize a thread of the enemy's soul to tug their physical form toward you. May not be used on enemies higher than level ${$PL+1} or which are marked as boss enemies.", description = "Afferra un filo dell'anima del nemico per attirarne a te la forma fisica. Non può essere usato sui nemici di livello superiore a ${$PL+1} o contrassegnati come boss." },
    [1219101] = { en = "Your next Imp, Voidwalker, Succubus, Incubus, Felhunter, or Felguard Summon spell has its casting time reduced by $/1000;s1 sec, and does not cost a Soul Shard or Mana.", description = "Il tempo di lancio del tuo prossimo incantesimo Evocazione di Imp, Camminatore del Vuoto, Succube, Incubo, Vilcacciatore o Vilguardia è ridotto di $/1000;s1 s e non costa una Scheggia d'Anima né mana." },
    [1219110] = { en = "$@spelldesc1219093", description = "$@spelldesc1219093" },
    [1219111] = { en = "$@spelldesc1219093", description = "$@spelldesc1219093" },
    [1219121] = { en = "Inflict Blood Plague upon the enemy target which deals $M1 Shadow damage every $t1 sec for $d.", description = "Infligge Peste del Sangue al bersaglio nemico, causando $M1 danni d'Ombra ogni $t1 sec per $d." },
    [1219124] = { en = "Inflict Frost Fever upon the enemy target which deals $M1 Frost damage every $t1 sec for $d.", description = "Infligge Febbre del Gelo al bersaglio nemico, causando $M1 danni da Gelo ogni $t1 sec per $d." },
    [1219150] = { en = "Improves attack and spell speed by $s1%. Increases nature damage taken by $s2%.", description = "Migliora la velocità d'attacco e di lancio degli incantesimi del $s1%. Aumenta i danni da Natura subiti del $s2%." },
    [1219153] = { en = "Mark an enemy. Whenever they deal damage, the target is healed for $M1% of their maximum health. Lasts $d or up to $U hits.\r\n\r\nStacks are not depleted on Undead targets. Only one Mark of Blood can be active on a target at a time.", description = "Marchia un nemico. Ogni volta che infligge danni, il bersaglio viene curato del $M1% della sua salute massima. Dura $d o fino a $U colpi.\r\n\r\nGli accumuli non si consumano sui bersagli Non Morti. Su un bersaglio può essere attiva una sola Marchio del Sangue alla volta." },
    [1219161] = { en = "$@spelldesc1219153", description = "$@spelldesc1219153" },
    [1219176] = { en = "Obliterate your target, dealing $M1 damage.\r\n\r\nAn infection of Blood Plague or Frost Fever on your target each increase the damage dealt by $M2%.", description = "Annienta il bersaglio, infliggendo $M1 danni.\r\n\r\nOgni infezione di Peste del Sangue o Febbre del Gelo sul bersaglio aumenta i danni inflitti del $M2%." },
    [1219178] = { en = "$@spelldesc1219176", description = "$@spelldesc1219176" },
    [1219275] = { en = "Gain the Devouring Plague ability:\r\n\r\n$@spellicon19280\r\n$@spelldesc19280", description = "Ottieni l'abilità Piaga divoratrice:\r\n\r\n$@spellicon19280\r\n$@spelldesc19280" },
    [1219359] = { en = "Any damage from an Undead attacker which would otherwise kill you will instead reduce you to $s2% of your maximum health (or your current health, whichever is lower). In addition, all damage taken from Undead will be reduced by $400024s1% for $400024d.  This effect cannot occur more than once per minute.", description = "Qualsiasi danno di un attaccante Non Morto che altrimenti ti ucciderebbe ti riduce invece al $s2% della tua salute massima (o alla salute attuale, se inferiore). Inoltre, tutti i danni subiti dai Non Morti vengono ridotti del $400024s1% per $400024d. Questo effetto non può verificarsi più di una volta al minuto." },
    [1219387] = { en = "Periodically launches flame bolts in the air, dealing $1219388s1 damage.", description = "Lancia periodicamente dardi infuocati in aria, infliggendo $1219388s1 danni." },
    [1219503] = { en = "Reduces your size and the threat you generate by $s1% for $d.", description = "Riduce la tua taglia e la minaccia che generi del $s1% per $d." },
    [1219507] = { en = "Permanently adds to a shoulder slot item increased healing done by magical spells and effects up to $s2 and also increases your mana regen by $s3 mana per 5 sec.", description = "Aggiunge permanentemente a un oggetto per spalle cure aumentate, fino a $s2, inflitte da incantesimi ed effetti magici e aumenta inoltre la rigenerazione del mana di $s3 mana ogni 5 sec." },
    [1219510] = { en = "Permanently adds to a shoulder slot item increased damage and healing done by magical spells and effects up to $1220735s1 and also increases your chance to land a critical strike by $1220735s3%.", description = "Aggiunge permanentemente a un oggetto per spalle danni e cure aumentati, fino a $1220735s1, inflitti da incantesimi ed effetti magici e aumenta inoltre la probabilità di infliggere un colpo critico del $1220735s3%." },
    [1219511] = { en = "Permanently adds to a shoulder slot item increased Stamina by $1220754s2 and Defense by $1220754s3. ", description = "Aggiunge permanentemente a un oggetto per spalle un aumento di $1220754s2 alla Tempra e di $1220754s3 alla Difesa. " },
    [1219512] = { en = "Permanently adds to a shoulder slot item increased Attack Power by $1220743s3 and also increases your chance to land a critical strike by $1220743s2%.", description = "Aggiunge permanentemente a un oggetto per spalle un aumento di $1220743s3 alla Potenza d'attacco e aumenta anche del $1220743s2% la probabilità di infliggere un colpo critico." },
    [1219521] = { en = "+$s1 Attack Power when fighting Undead and Demons.  It also allows the acquisition of Scourgestones on behalf of the Argent Dawn.", description = "+$s1 alla Potenza d'attacco quando si combattono Non morti e Demoni.  Consente inoltre di ottenere Pietre del Flagello per conto dell'Alba d'Argento." },
    [1219552] = { en = "Increases damage and healing done by magical spells and effects of all party members within $a1 yards by up to $s1.  This specific effect does not stack from multiple sources.", description = "Aumenta fino a $s1 i danni e le cure inflitti dagli incantesimi ed effetti magici di tutti i membri del gruppo entro $a1 metri.  Questo effetto specifico non si cumula se proviene da più fonti." },
    [1219553] = { en = "Increases healing done by up to $s1 and damage done by up to $s2 for all magical spells and effects of all party members within $a1.  This specific effect does not stack from multiple sources.", description = "Aumenta fino a $s1 le cure e fino a $s2 i danni di tutte le magie ed effetti magici di tutti i membri del gruppo entro $a1.  Questo effetto specifico non si cumula se proviene da più fonti." },
    [1219557] = { en = "Increases spell casting speed of all party members within $a1 yards by $s1%.  This specific effect does not stack from multiple sources.", description = "Aumenta del $s1% la velocità di lancio degli incantesimi di tutti i membri del gruppo entro $a1 metri.  Questo effetto specifico non si cumula se proviene da più fonti." },
    [1219558] = { en = "Increases the spell critical chance of all party members within $a1 yards by $s1%.  This specific effect does not stack from multiple sources.", description = "Aumenta del $s1% la probabilità di colpo critico degli incantesimi di tutti i membri del gruppo entro $a1 metri.  Questo effetto specifico non si cumula se proviene da più fonti." },
    [1219577] = { en = "Permanently enchant an Off-Hand to add $M1 to intellect.", description = "Incanta permanentemente una mano secondaria per aggiungere $M1 all'intelletto." },
    [1219578] = { en = "Permanently enchant an Off-Hand to add $M1 to spirit.", description = "Incanta permanentemente una mano secondaria per aggiungere $M1 allo spirito." },
    [1219579] = { en = "Permanently enchant an Off-Hand to add $M1 to intellect and $M2 to spirit.", description = "Incanta permanentemente una mano secondaria per aggiungere $M1 all'intelletto e $M2 allo spirito." },
    [1219580] = { en = "Permanently enchant a 2H Weapon to add $M1 Spell Power.", description = "Incanta permanentemente un'arma a due mani per aggiungere $M1 alla potenza magica." },
    [1219581] = { en = "Permanently enchant a Shield to add $M1 to stamina.", description = "Incanta permanentemente uno scudo per aggiungere $M1 alla tempra." },
    [1219587] = { en = "Permanently enchant a Cloak to add $M1 to agility.", description = "Incanta permanentemente un mantello per aggiungere $M1 all'agilità." },
